// Builds the list of channels: first the ones typed into the form, then the ones YouTube's search
// returned for the topic. Typed channels may be @handles, bare handles, channel links (also the old
// /c/ and /user/ links) or channel IDs (UC...), one per line or separated by commas.
// Anything that is not a channel is listed on the result page with the reason.
const form = $('Settings').first().json;
const maxChannels = Number(form.max_channels) || 10;
const minAgeDays = Number(form.min_age_days) || 3;
const minGroup = Number(form.min_videos_per_format) || 5;
const fromTopic = Number(form.channels_from_topic) || 8;
const minSubscribers = Number(form.topic_min_subscribers) || 0;
const maxAgeDays = Number(form.outlier_max_age_days) || 90;
const minUsualViews = Number(form.topic_min_usual_views) || 0;
// Thumbnails are loaded by the viewer's browser from YouTube's image server. 0 in Settings leaves them out.
const showThumbnails = Number(form.show_thumbnails ?? 1) !== 0;

// The form is public once the workflow is active, so the text is cut before it is read.
const raw = String(form.channels ?? '').slice(0, 5000);
const topic = String(form.topic ?? '').replace(/\s+/g, ' ').trim().slice(0, 80);
const factorIn = parseFloat(String(form.factor ?? '').replace(',', '.'));
const factor = Number.isFinite(factorIn) && factorIn >= 1.2 && factorIn <= 50 ? factorIn : 2;

// Every address requested later is built here or from a channel ID, always on www.youtube.com.
const YOUTUBE = 'https://www.youtube.com/';
// YouTube publishes a channel's long videos as a feed of their own: the channel ID with the prefix UULF.
const longFeedOf = (id) => `${YOUTUBE}feeds/videos.xml?playlist_id=UULF${id.slice(2)}`;
const NO_LOOKUP = `${YOUTUBE}feeds/videos.xml?channel_id=UNRESOLVED`;
const NAME = '[\\p{L}\\p{N}_.·-]'; // handles may use letters and digits of any alphabet
const handleAt = new RegExp(`@(${NAME}{3,30})(?!${NAME})`, 'u');
const bareHandle = new RegExp(`^${NAME}{3,30}$`, 'u');
const oldLink = new RegExp(`(?:^|\\/\\/|\\.)youtube\\.com\\/(c|user)\\/(${NAME}{1,100})`, 'iu');
const videoLink = /youtu\.be\/|[?&]v=|\/shorts\/[\w-]{6,}|\/playlist|\/live\/|\/embed\//i;

const seen = new Set();
const channels = [];
let overLimit = 0;

for (const line of raw.split(/[\n\r,;]+/)) {
  const text = line.trim();
  if (!text) continue;

  const channel = { input: text.slice(0, 80), origin: 'form', handle: null, channel_id: null, page_url: NO_LOOKUP, problem: null };
  const id = (text.match(/^(UC[\w-]{22})$/) || text.match(/\/channel\/(UC[\w-]{22})(?![\w-])/) || [])[1];
  const handle = (text.match(handleAt) || [])[1];
  const old = text.match(oldLink);
  let key;

  if (id) {
    // A channel ID needs no lookup. Its long-video feed is requested in place of the 2 MB channel
    // page; "Extract channel ID" keeps the answer, so that request is not made a second time.
    channel.channel_id = id;
    channel.page_url = longFeedOf(id);
    key = id;
  } else if (handle || bareHandle.test(text)) {
    // ucbcb=1 stops YouTube from answering with its cookie consent page
    // (seen on 4 of 12 requests from the EU without it).
    channel.handle = handle || text;
    channel.page_url = `${YOUTUBE}@${encodeURIComponent(channel.handle)}?ucbcb=1`;
    key = channel.handle;
  } else if (old) {
    channel.page_url = `${YOUTUBE}${old[1].toLowerCase()}/${encodeURIComponent(old[2])}?ucbcb=1`;
    key = `${old[1]}/${old[2]}`;
  } else {
    channel.problem = videoLink.test(text)
      ? 'this is a video or playlist link, enter the channel instead'
      : 'not recognised: enter an @handle, a channel link or a channel ID';
    key = text;
  }

  key = key.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  if (channels.length >= maxChannels) { overLimit += 1; continue; }
  channels.push(channel);
}

// Channels for the topic. This node gets the search page only when a topic was entered.
let searchNote = null;
if (topic) {
  const html = String(($input.first().json || {}).data ?? '');
  const subscribers = (block) => {
    const m = block.match(/"videoCountText":\{.{0,300}?([\d.,]+)\s*(K|M|B|thousand|million|billion)?\s+subscribers?"/i);
    if (!m) return null; // hidden, zero, or worded in another language
    const unit = { k: 1e3, thousand: 1e3, m: 1e6, million: 1e6, b: 1e9, billion: 1e9 }[(m[2] || '').toLowerCase()] || 1;
    return parseFloat(m[1].replace(/,/g, '')) * unit;
  };
  const results = html.split('"channelRenderer":{').slice(1, 41).map((block) => ({
    id: (block.match(/^"channelId":"(UC[\w-]{22})"/) || [])[1],
    subscribers: subscribers(block.slice(0, 8000)),
  })).filter((r) => r.id);
  // Channels stay in YouTube's own order, the most relevant first: sorting by size brought in large
  // channels that had little to do with the topic. Tiny ones are handled later, by their usual views.
  // If no count on the page can be read, the page is in another language and every channel is kept.
  // If some can, a channel without one hides its count or has none, and is left out.
  const countsReadable = results.some((r) => r.subscribers !== null);
  const big = results.filter((r) => (r.subscribers === null ? !countsReadable : r.subscribers >= minSubscribers));

  if (!html) searchNote = 'YouTube search did not answer';
  else if (/consent\.youtube\.com\/(m|save)|before you continue/i.test(html) && !results.length) searchNote = 'YouTube search returned a consent page';
  else if (/unusual traffic|google\.com\/sorry/i.test(html) && !results.length) searchNote = 'YouTube is limiting requests from this server, try again later';
  else if (!results.length) searchNote = 'YouTube search found no channels for this topic';
  else if (!big.length) searchNote = `YouTube search found only channels with fewer than ${minSubscribers} subscribers`;

  // A typed handle may turn out to be one of the found channels. That is known only after the
  // lookup, so a few spare channels are passed on and "Extract channel ID" keeps the right number.
  // Two at most: every spare channel is one more request to YouTube.
  const spare = Math.min(2, channels.filter((c) => !c.channel_id && !c.problem).length);
  let added = 0;
  for (const r of big) {
    if (added >= fromTopic + spare || channels.length >= maxChannels + spare) break;
    if (seen.has(r.id.toLowerCase())) continue;
    seen.add(r.id.toLowerCase());
    channels.push({ input: '', origin: 'topic', handle: null, channel_id: r.id, page_url: longFeedOf(r.id), problem: null });
    added += 1;
  }
}

// Always pass one item on, so the run reaches the result page and can say what went wrong.
if (channels.length === 0) {
  channels.push({
    input: raw.trim().slice(0, 80), origin: 'form', handle: null, channel_id: null, page_url: NO_LOOKUP,
    problem: topic ? 'no channel to read' : 'no topic or channel was entered',
  });
}

return channels.map((c) => ({
  json: {
    ...c, factor, topic, search_note: searchNote,
    min_age_days: minAgeDays, max_age_days: maxAgeDays, min_group: minGroup, min_usual_views: minUsualViews,
    max_channels: maxChannels, channels_from_topic: fromTopic, over_limit: overLimit, show_thumbnails: showThumbnails,
  },
}));

// Finds each channel's ID in its public page, then builds the addresses of its two public feeds:
// long videos and Shorts. Only markers that belong to the page's own channel are used, never
// links to other channels.
const wanted = $('Parse channel list').all();
const answers = $input.all();

// n8n links every answer to the item it was requested for. Without those links the order is
// trusted only when no answer is missing; otherwise nothing is matched and nothing is guessed.
const linkOf = (item) => {
  const pair = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  if (typeof pair === 'number') return pair;
  return pair && typeof pair.item === 'number' ? pair.item : null;
};
const pages = new Map();
if (answers.length && answers.every((a) => linkOf(a) !== null)) answers.forEach((a) => pages.set(linkOf(a), a.json || {}));
else if (answers.length === wanted.length) answers.forEach((a, i) => pages.set(i, a.json || {}));

const resolved = wanted.map((item, i) => {
  const channel = item.json;
  const html = String((pages.get(i) || {}).data ?? '');

  let id = channel.channel_id;
  let problem = channel.problem || null;
  if (!id && !problem) {
    const found =
      html.match(/<link rel="canonical" href="https:\/\/www\.youtube\.com\/channel\/(UC[\w-]{22})"/) ||
      html.match(/feeds\/videos\.xml\?channel_id=(UC[\w-]{22})(?![\w-])/) ||
      html.match(/"externalId":"(UC[\w-]{22})"/);
    id = found ? found[1] : null;

    if (!id) {
      if (!html) problem = 'YouTube did not answer for this channel';
      else if (/consent\.youtube\.com|before you continue/i.test(html)) problem = 'YouTube returned a consent page instead of the channel';
      else if (/unusual traffic|google\.com\/sorry/i.test(html)) problem = 'YouTube is limiting requests from this server, try again later';
      else problem = 'channel not found';
    }
  }

  // For a channel given by its ID the request before this node was its long-video feed, not a
  // page. If a feed came back it is kept, so it is not requested again. A real feed is about 45 KB.
  const longFeed = channel.channel_id && html.includes('<feed') && html.length < 500000 ? html : null;

  return { json: { ...channel, channel_id: id, problem, long_feed: longFeed } };
});

// The same channel can arrive twice: typed as a handle and as an ID, or typed and also found for the topic.
// Typed channels are all kept; found channels fill up to the limits from Settings.
const seenIds = new Set();
const maxChannels = wanted[0]?.json?.max_channels ?? 10;
const fromTopic = wanted[0]?.json?.channels_from_topic ?? 8;
let kept = 0;
let keptFromTopic = 0;
const channels = resolved.filter((item) => {
  const { channel_id: id, origin } = item.json;
  if (id && seenIds.has(id)) return false;
  if (origin === 'topic' && (keptFromTopic >= fromTopic || kept >= maxChannels)) return false;
  if (id) seenIds.add(id);
  if (origin === 'topic') keptFromTopic += 1;
  kept += 1;
  return true;
});

// YouTube publishes a channel's uploads as two feeds of 15 videos each: long videos only (UULF)
// and Shorts only (UUSH). Their addresses are the channel ID with another prefix. One item is
// passed on per feed still to request; "channel_index" tells "Find outliers" which items belong together.
const FEEDS = 'https://www.youtube.com/feeds/videos.xml?';
return channels.flatMap((item, index) => {
  const id = item.json.channel_id;
  if (!id) return [{ json: { ...item.json, channel_index: index, feed_url: `${FEEDS}channel_id=UNRESOLVED` } }];
  return (item.json.long_feed ? ['UUSH'] : ['UULF', 'UUSH']).map((prefix) => ({
    json: { ...item.json, channel_index: index, feed_url: `${FEEDS}playlist_id=${prefix}${id.slice(2)}` },
  }));
});

// Reads each channel's public feeds and marks videos that did far better than usual
// for that channel and that format. Shorts and long videos are never compared with each other,
// and a video is never part of its own "usual".
// "Extract channel ID" passes one item per feed to request: a channel's Shorts, and its long videos
// unless that feed is already in the item as "long_feed".
const requests = $('Extract channel ID').all().map((i) => i.json);
const channels = [];
requests.forEach((request, i) => {
  const n = Number.isInteger(request.channel_index) ? request.channel_index : i;
  if (!channels[n]) channels[n] = { ...request, feeds: [] };
  channels[n].feeds.push(i);
});
const factor = channels[0]?.factor ?? 2;
const minAge = channels[0]?.min_age_days ?? 3;
const minGroup = channels[0]?.min_group ?? 5;
const maxAge = channels[0]?.max_age_days ?? 90;
const minUsualViews = channels[0]?.min_usual_views ?? 0;
const now = $now.toMillis();

// n8n links every answer to the item it was requested for. Without those links the order is
// trusted only when no answer is missing; otherwise nothing is matched and nothing is guessed.
const answers = $input.all();
const linkOf = (item) => {
  const pair = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  if (typeof pair === 'number') return pair;
  return pair && typeof pair.item === 'number' ? pair.item : null;
};
const feeds = new Map();
if (answers.length && answers.every((a) => linkOf(a) !== null)) answers.forEach((a) => feeds.set(linkOf(a), a.json || {}));
else if (answers.length === requests.length) answers.forEach((a, i) => feeds.set(i, a.json || {}));

const decode = (s) => String(s ?? '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/&#39;|&apos;/g, "'").replace(/&amp;/g, '&')
  .replace(/[￼�​-‏﻿]/g, ''); // placeholders and invisible marks left in some titles
const pick = (text, re) => (text.match(re) || [])[1];
const median = (list) => {
  const s = [...list].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
};
const round1 = (n) => Math.round(n * 10) / 10;

const channelRows = [];
const videos = [];

channels.forEach((channel) => {
  const row = { input: channel.input, origin: channel.origin || 'form', channel_id: channel.channel_id, name: null, problem: channel.problem, videos: 0, settled_long: 0, settled_short: 0, usual_long: null, usual_short: null };
  channelRows.push(row);
  if (row.problem) return;

  // YouTube answers "not found" for a format the channel does not have, so one missing feed is
  // not an error. Both missing is.
  const xmls = [channel.long_feed, ...channel.feeds.map((n) => feeds.get(n)?.data)]
    .map((text) => String(text ?? '')).filter((text) => text.includes('<feed'));
  const xml = xmls[0] || '';
  // A real feed holds 15 videos. The cut keeps a broken or hostile answer from being processed whole.
  const seenVideos = new Set();
  const entries = xmls.flatMap((text) => text.split('<entry>').slice(1, 51)).filter((entry) => {
    const videoId = pick(entry, /<yt:videoId>([^<]*)/);
    if (videoId && seenVideos.has(videoId)) return false; // a video sent in both feeds is counted once
    if (videoId) seenVideos.add(videoId);
    return true;
  });
  if (xmls.length === 0) {
    // YouTube feeds have short outages (404 for a channel that exists), and a single failed request is not repeated.
    row.problem = 'YouTube did not return the feed; this is often temporary, run again in a few minutes';
    return;
  }
  if (entries.length === 0) {
    row.problem = 'the feed has no public videos';
    return;
  }
  // Second guard against mixed-up answers: the videos must name the channel that was asked for.
  const owners = entries.map((e) => pick(e, /<yt:channelId>([^<]*)/)).filter(Boolean);
  if (owners.some((owner) => owner !== channel.channel_id && `UC${owner}` !== channel.channel_id)) {
    row.problem = 'the feed returned belongs to another channel';
    return;
  }
  row.name = decode(pick(xml, /<author>\s*<name>([^<]*)/) || pick(xml, /<title>([^<]*)/) || channel.input);

  const list = entries.map((entry) => {
    const url = pick(entry, /<link rel="alternate" href="([^"]*)"/) || '';
    const published = pick(entry, /<published>([^<]*)/);
    const publishedMs = new Date(published).getTime();
    const views = Number(pick(entry, /<media:statistics views="(\d+)"/));
    // The feed calls it a star rating, but the count is the number of likes.
    const likes = Number(pick(entry, /<media:starRating count="(\d+)"/));
    return {
      channel: row.name,
      video_id: pick(entry, /<yt:videoId>([^<]*)/) || null,
      title: decode(pick(entry, /<title>([^<]*)/)),
      url,
      thumbnail: pick(entry, /<media:thumbnail url="([^"]*)"/) || null,
      published,
      age_days: Number.isFinite(publishedMs) ? round1((now - publishedMs) / 86400000) : null,
      views,
      likes: Number.isFinite(likes) ? likes : null,
      likes_per_1k: Number.isFinite(likes) && views > 0 ? round1((likes / views) * 1000) : null,
      // The feed links a Short as /shorts/ID, so the format is known and not guessed from length.
      format: /\/shorts\//.test(url) ? 'short' : 'long',
      status: 'not judged',
      reason: '',
      usual_views: null,
      compared_with: null,
      multiple: null,
      usual_likes_per_1k: null,
      like_ratio: null,
      too_old: false,
      note: '',
    };
  });
  row.videos = list.length;

  for (const format of ['long', 'short']) {
    const group = list.filter((v) => v.format === format);
    // Only videos old enough to have collected their first views can describe what is usual.
    const settled = group.filter((v) => Number.isFinite(v.views) && v.age_days !== null && v.age_days >= minAge);
    row[`settled_${format}`] = settled.length;
    if (settled.length >= minGroup) row[`usual_${format}`] = Math.round(median(settled.map((v) => v.views)));
    // A channel the search brought in is judged only if it has an audience: 350 usual views turn
    // any small spike into a 30x lead. Channels typed into the form are the user's own choice.
    const tooSmall = channel.origin === 'topic' && row[`usual_${format}`] !== null && row[`usual_${format}`] < minUsualViews;
    row[`small_${format}`] = tooSmall;

    for (const video of group) {
      if (!Number.isFinite(video.views)) { video.reason = 'no view count in the feed'; continue; }
      if (video.age_days === null) { video.reason = 'no publish date in the feed'; continue; }
      if (settled.length < minGroup) { video.reason = `fewer than ${minGroup} ${format === 'short' ? 'Shorts' : 'long videos'} to compare with`; continue; }
      if (tooSmall) { video.reason = `found channel with usual views under ${minUsualViews}: enter it yourself to judge it`; continue; }

      const others = settled.filter((v) => v !== video);
      const usual = median(others.map((v) => v.views));
      if (!(usual > 0)) { video.reason = 'usual views are zero'; continue; }

      const multiple = round1(video.views / usual);
      const young = !(video.age_days >= minAge);
      if (young && multiple < factor) {
        video.reason = `younger than ${minAge} days and not ahead yet`;
        continue;
      }

      video.usual_views = Math.round(usual);
      video.compared_with = others.length;
      video.multiple = multiple;
      // A young video is compared with older ones, so being ahead already is a strong sign.
      video.status = multiple >= factor ? (young ? 'early outlier' : 'outlier') : 'usual';
      // An old outlier still shapes what is usual, but it is not news: it is counted, not listed.
      video.too_old = video.status === 'outlier' && video.age_days > maxAge;

      const rates = others.map((v) => v.likes_per_1k).filter((r) => r !== null);
      if (video.likes_per_1k !== null && rates.length >= minGroup - 1) {
        const usualRate = median(rates);
        if (usualRate > 0) {
          video.usual_likes_per_1k = round1(usualRate);
          video.like_ratio = Math.round((video.likes_per_1k / usualRate) * 100) / 100;
        }
      }

      const typicalAge = median(others.map((v) => v.age_days));
      if (video.age_days > 30 && video.age_days > 2 * typicalAge) {
        video.note = 'older than the videos it is compared with, so part of the lead may be time';
      }
    }
  }
  videos.push(...list);
});

return [{
  json: {
    generated_at: new Date(now).toISOString(),
    factor,
    topic: channels[0]?.topic || '',
    search_note: channels[0]?.search_note || null,
    min_age_days: minAge,
    max_age_days: maxAge,
    min_group: minGroup,
    max_channels: channels[0]?.max_channels ?? 10,
    over_limit: channels[0]?.over_limit ?? 0,
    show_thumbnails: channels[0]?.show_thumbnails ?? true,
    channels: channelRows,
    videos,
  },
}];

// Builds the page shown to the person who filled in the form.
// n8n's own page lays <body> out as a column, so the page gets its own wrapper and every style
// is written for that wrapper only.
const data = $input.first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const num = (n) => (Number.isFinite(Number(n)) ? Number(n).toLocaleString('en-US') : '&mdash;');
const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
// Text from the feed is shown as text. Links and pictures are used only when they point to YouTube.
const videoLink = (u) => (/^https:\/\/www\.youtube\.com\/(watch\?v=|shorts\/)[\w-]+$/.test(String(u)) ? u : null);
const picture = (id) => (/^[\w-]{6,20}$/.test(String(id)) ? `https://i.ytimg.com/vi/${id}/mqdefault.jpg` : null);

const isOutlier = (v) => v.status === 'outlier' || v.status === 'early outlier';
const judged = data.videos.filter((v) => v.status !== 'not judged');
const outliers = judged.filter((v) => isOutlier(v) && !v.too_old).sort((a, b) => b.multiple - a.multiple);
const older = judged.filter((v) => isOutlier(v) && v.too_old).length;
const early = outliers.filter((v) => v.status === 'early outlier');
const notJudged = data.videos.filter((v) => v.status === 'not judged');
const readable = data.channels.filter((c) => !c.problem);

// What the topic search contributed, or why it contributed nothing.
const fromTopic = data.channels.filter((c) => c.origin === 'topic').length;
let topicLine = '';
if (data.topic && data.search_note) {
  topicLine = `<p><i>Topic "${esc(data.topic)}": ${esc(data.search_note)}.${readable.length ? '' : ' Enter channels yourself instead.'}</i></p>`;
} else if (data.topic) {
  topicLine = `<p>${plural(fromTopic, 'channel', 'channels')} came from YouTube's search for "${esc(data.topic)}". They are YouTube's picks, not a checked list: look at the Channels table, then run again with the channels you trust.</p>`;
}

const reasons = {};
for (const v of notJudged) reasons[v.reason] = (reasons[v.reason] || 0) + 1;

const likeCell = (v) => {
  if (v.likes_per_1k === null) return '&mdash;';
  if (v.like_ratio === null) return `${v.likes_per_1k}`;
  const reading = v.like_ratio >= 1.25 ? 'more than usual' : v.like_ratio <= 0.8 ? 'less than usual' : 'about as usual';
  return `${v.likes_per_1k}<br><small>usual ${v.usual_likes_per_1k}<br>${reading}</small>`;
};

const outlierRow = (v) => {
  const link = videoLink(v.url);
  const img = data.show_thumbnails ? picture(v.video_id) : null;
  const title = link ? `<a href="${esc(link)}" target="_blank" rel="noopener noreferrer">${esc(v.title)}</a>` : esc(v.title);
  return `<tr>
<td>${img ? `<img src="${esc(img)}" alt="" width="160" height="90" referrerpolicy="no-referrer" loading="lazy">` : ''}</td>
<td><b>${v.multiple}&times;</b>${v.status === 'early outlier' ? '<br><small><b>early</b></small>' : ''}</td>
<td>${num(v.views)}<br><small>usual ${num(v.usual_views)}<br>from ${plural(v.compared_with, 'video', 'videos')}</small></td>
<td>${likeCell(v)}</td>
<td>${v.age_days < 1 ? 'under a day' : plural(Math.round(v.age_days), 'day', 'days')}</td>
<td>${title}<br><small>${esc(v.channel)}</small>${v.note ? `<br><small><i>${esc(v.note)}</i></small>` : ''}</td>
</tr>`;
};

const outlierTable = (heading, format) => {
  const rows = outliers.filter((v) => v.format === format);
  const judgedHere = judged.filter((v) => v.format === format).length;
  if (!judgedHere) return `<h2>${heading}</h2><p>None could be judged. See "Not judged" below.</p>`;
  if (!rows.length) return `<h2>${heading}</h2><p>${plural(judgedHere, 'video', 'videos')} judged, none from the last ${data.max_age_days} days reached ${data.factor}&times; the usual views.</p>`;
  return `<h2>${heading}: ${plural(rows.length, 'outlier', 'outliers')} among ${judgedHere} judged</h2>
<table><tr><th></th><th>Lead</th><th>Views</th><th>Likes per 1,000&nbsp;views</th><th>Age</th><th>Video</th></tr>
${rows.map(outlierRow).join('\n')}</table>`;
};

// How many videos of one format a channel has to compare, and their median views.
const formatCell = (c, format) => {
  if (c.problem) return '';
  const count = c[`settled_${format}`];
  const usual = c[`usual_${format}`];
  if (!count) return '&mdash;';
  const verdict = usual === null ? 'too&nbsp;few to&nbsp;judge' : `usual&nbsp;${num(usual)}`;
  return `${count}<br><small>${verdict}${c[`small_${format}`] ? '<br>too&nbsp;small to&nbsp;judge' : ''}</small>`;
};

const channelRows = data.channels.map((c) => `<tr>
<td>${c.origin === 'topic' ? '<small>found for the topic</small>' : esc(c.input)}</td>
<td>${c.problem ? `<i>${esc(c.problem)}</i>` : esc(c.name)}</td>
<td>${c.problem ? '' : c.videos}</td>
<td>${formatCell(c, 'long')}</td>
<td>${formatCell(c, 'short')}</td>
</tr>`).join('\n');

const reasonItems = Object.entries(reasons).map(([reason, count]) => `<li>${count}: ${esc(reason)}</li>`).join('');

// A ready text for any AI chat: the outliers next to ordinary videos of the same channels (lead
// closest to 1x), so there is something to compare them with. The weakest videos would be a worse
// yardstick: flops differ for reasons of their own. The workflow itself calls no AI.
const oneLine = (v) => `${v.multiple >= 0.1 ? `${v.multiple}x` : 'under 0.1x'} | ${v.format === 'short' ? 'Short' : 'Long video'} | ${num(v.views)} views | ${String(v.channel).replace(/\s+/g, ' ').trim()} | ${String(v.title).replace(/\s+/g, ' ').trim()}`;
const plain = judged.filter((v) => v.status === 'usual').sort((a, b) => Math.abs(a.multiple - 1) - Math.abs(b.multiple - 1)).slice(0, 20)
  .sort((a, b) => b.multiple - a.multiple);
const aiPrompt = outliers.length ? [
  `Below are YouTube videos${data.topic ? ` on the topic "${data.topic}"` : ' from one niche'}. Lead is a video's views divided by the usual views of its own channel for the same format (Shorts or long videos).`,
  '',
  `OUTLIERS, at least ${data.factor}x the usual views (lead | format | views | channel | title):`,
  ...outliers.slice(0, 25).map(oneLine),
  ...(plain.length ? ['', 'ORDINARY VIDEOS of the same channels, lead closest to 1x (lead | format | views | channel | title):', ...plain.map(oneLine)] : []),
  '',
  'Please answer:',
  '1. What are the 3 strongest things the outlier titles have in common that the ordinary titles lack: topic, promise, wording, format?',
  `2. Which of these patterns may be chance? There ${outliers.length === 1 ? 'is only 1 outlier' : `are only ${outliers.length} outliers`}.`,
  // The instruction sits inside the bracket, so it disappears when the bracket is replaced.
  '3. Suggest 5 video ideas with titles for my channel. My channel is about: [replace this bracket with one line about your channel; if it is still here, ask me before suggesting ideas]',
  'Use only this list, quote titles exactly as written, and say so where the list is too short to tell.',
].join('\n') : '';
const aiBlock = aiPrompt ? `<h2>Why did these work? Ask an AI</h2>
<p>This page shows what did well, not why. Select the text in the box, copy it and paste it into any AI chat. Replace the bracket near the end with one line about your channel.</p>
<pre>${esc(aiPrompt)}</pre>` : '';

const style = `<style>
body{display:block;margin:0;background:#fff}
.outlier-report{display:flex;flex-direction:row;gap:32px;align-items:flex-start;max-width:1400px;margin:0 auto;padding:24px;box-sizing:border-box;font:15px/1.5 system-ui,sans-serif;color:#1f2328;text-align:left}
.outlier-report aside{flex:0 0 290px;position:sticky;top:16px;max-height:calc(100vh - 32px);overflow:auto;box-sizing:border-box;background:#f6f8fa;border:1px solid #d0d7de;border-radius:8px;padding:4px 18px 10px;font-size:14px}
.outlier-report aside h2{margin-top:14px} .outlier-report aside p{margin:10px 0}
.outlier-report main{flex:1;min-width:0}
@media (max-width:1000px){.outlier-report{display:block} .outlier-report aside{position:static;max-height:none;margin-bottom:24px}}
.outlier-report table{border-collapse:collapse;width:100%;margin:8px 0 24px}
.outlier-report td,.outlier-report th{border:1px solid #d0d7de;padding:8px;text-align:left;vertical-align:top}
.outlier-report th{background:#f6f8fa} .outlier-report small{color:#57606a}
.outlier-report h1{font-size:1.5em;margin-top:0} .outlier-report h2{font-size:1.15em;margin-top:28px}
.outlier-report img{display:block;border-radius:4px}
.outlier-report pre{white-space:pre-wrap;overflow-wrap:anywhere;margin:8px 0 24px;padding:12px;background:#f6f8fa;border:1px solid #d0d7de;border-radius:8px;font:13px/1.5 ui-monospace,Consolas,monospace;-webkit-user-select:all;user-select:all}
.outlier-report td small,.outlier-report td b{white-space:nowrap} .outlier-report td:last-child small{white-space:normal}
</style>`;

// A form sent empty gets one short page instead of empty tables. The wording of the problem
// comes from "Parse channel list".
const nothingEntered = data.channels.length === 1 && data.channels[0].problem === 'no topic or channel was entered';
const html = nothingEntered ? `${style}
<div class="outlier-report">
<main>
<h1>Nothing was entered</h1>
<p>Open the form again and enter a topic, one or more YouTube channels, or both.</p>
<p><small>Topic example: skincare routine. Channel example: @channelname.</small></p>
</main>
</div>` : `${style}
<div class="outlier-report">
<aside>
<h2>How to read this</h2>
<p><b>Outlier</b>: a video that got far more views than its channel usually gets. Here that means ${data.factor}&times; or more.</p>
<p><b>Lead</b>: how many times more. 5&times; means five times the channel's usual views.</p>
<p><b>Usual</b>: what this channel's other recent videos of the same kind typically get. Shorts are compared only with Shorts, long videos only with long videos.</p>
<p><b>Likes per 1,000 views</b>: did the people who watched also like it? Outliers often get fewer likes per view, so "less than usual" alone is not a bad sign. "More than usual" means viewers reacted more than they normally do.</p>
<p><b>Early</b>: the video is under ${data.min_age_days} days old and already this far ahead. Look at these first.</p>
<p><b>Not here</b>: videos older than ${data.max_age_days} days, and channels with too few videos to compare. The reasons are at the bottom of the page.</p>
<p><b>What to do</b>: open the top videos and look at the title and the thumbnail. For the why, copy the text under the tables into an AI chat.</p>
<p><small>The numbers are this workflow's own maths from public YouTube data, not official YouTube metrics.</small></p>
</aside>
<main>
<h1>Outlier videos in your niche</h1>
<p>${readable.length} of ${plural(data.channels.length, 'channel', 'channels')} read, ${plural(data.videos.length, 'video', 'videos')} in their public feeds, ${judged.length} judged.
<b>${plural(outliers.length, 'video', 'videos')} from the last ${data.max_age_days} days got at least ${data.factor}&times; the usual views</b> for the same channel and format${early.length ? `, ${early.length} of them while still younger than ${data.min_age_days} days` : ''}.${older ? ` ${plural(older, 'older outlier is', 'older outliers are')} not listed.` : ''}</p>
${topicLine}
${readable.length ? `${outlierTable('Long videos', 'long')}
${outlierTable('Shorts', 'short')}` : '<p>No channel could be read, so there is nothing to compare. Check the table below.</p>'}
${aiBlock}
<h2>Channels</h2>
<p>Check that each channel is the one you meant. The last two columns show how many videos the channel has to compare and its usual views.</p>
<table><tr><th>Entered or found</th><th>Channel</th><th>Videos read</th><th>Long videos to compare (usual views)</th><th>Shorts to compare (usual views)</th></tr>
${channelRows}</table>
${notJudged.length ? `<h2>Not judged: ${plural(notJudged.length, 'video', 'videos')}</h2><ul>${reasonItems}</ul>` : ''}
${data.over_limit ? `<p><i>${plural(data.over_limit, 'more channel was', 'more channels were')} left out: the limit is ${data.max_channels} per run.</i></p>` : ''}
<h2>The exact rules</h2>
<p><small>Usual is the median views of the channel's other videos of the same format (Shorts or long videos) that are at least ${data.min_age_days} days old.
The video itself is left out, so the usual in a row can be lower than the channel's figure in the Channels table.
YouTube's public feeds hold a channel's latest 15 long videos and its latest 15 Shorts. A format with fewer than ${data.min_group} videos to compare gets no verdict, and a format YouTube returned nothing for shows a dash.
Lead is views divided by usual. Views keep growing, so a video that is usual today can become an outlier later.
Outliers older than ${data.max_age_days} days are counted in the first lines but not listed. The limits are in the Settings node.
Generated ${esc(data.generated_at.slice(0, 16).replace('T', ' '))} UTC from public YouTube channel feeds.</small></p>
</main>
</div>`;

return [{
  json: {
    html,
    ai_prompt: aiPrompt,
    outliers: outliers.length,
    older_outliers: older,
    early_outliers: early.length,
    judged: judged.length,
    not_judged: notJudged.length,
    channels_read: readable.length,
  },
}];
